def count_no(arr, x):
    # 统计不包含数字 x 的子段数
    res = 0
    cnt = 0
    for v in arr:
        if v == x:
            res += cnt * (cnt + 1) // 2
            cnt = 0
        else:
            cnt += 1
    res += cnt * (cnt + 1) // 2
    return res

def count_no_pair(arr, x, y):
    # 统计不包含数字 x 和 y 的子段数（子段中只能出现剩下的那个数）
    res = 0
    cnt = 0
    for v in arr:
        if v == x or v == y:
            res += cnt * (cnt + 1) // 2
            cnt = 0
        else:
            cnt += 1
    res += cnt * (cnt + 1) // 2
    return res

def main():
    import sys
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    arr = list(map(int, input_data[1:]))

    total = n * (n + 1) // 2

    cnt0 = count_no(arr, 0)       # 不含0的子段数
    cnt1_all = count_no(arr, 1)     # 不含1的子段数
    cnt2_all = count_no(arr, 2)     # 不含2的子段数

    cnt01 = count_no_pair(arr, 0, 1)  # 不含0和1的子段数
    cnt02 = count_no_pair(arr, 0, 2)  # 不含0和2的子段数
    cnt12 = count_no_pair(arr, 1, 2)  # 不含1和2的子段数

    # 计算各个类别的子段个数
    cnt_mex0 = cnt0                                #缺省数=0的子段
    cnt_mex1 = cnt1_all - cnt01                    #缺省数=1的子段：包含0但不含1
    cnt_mex2 = cnt2_all - cnt02 - cnt12            #缺省数=2的子段：包含0和1但不含2
    cnt_mex3 = total - (cnt0 + cnt1_all + cnt2_all) + (cnt01 + cnt02 + cnt12)  #缺省数=3的子段

    # 最终答案
    ans = 1 * cnt_mex1 + 2 * cnt_mex2 + 3 * cnt_mex3
    print(ans)

if __name__ == '__main__':
